@extends('layouts.app') @section('content') @include('roster.partials.style') <div class="container-fluid py-4 roster-shell"><h3 class="roster-title">Roster Settings</h3><div class="row g-3"><div class="col-lg-4"><div class="card roster-card"><div class="card-body"><h5>Module Feature Toggle</h5><p class="text-muted">Disable Roster similarly to Car Passes and Utilities. Data is retained.</p><form method="post" action="{{ route('roster.settings.toggle') }}">@csrf<input type="hidden" name="enabled" value="0"><div class="form-check form-switch"><input class="form-check-input" type="checkbox" name="enabled" value="1" @checked(in_array(strtolower((string)$enabled),['1','true','yes','on']))><label class="form-check-label">Roster module enabled</label></div><button class="btn btn-steel mt-3">Save Module Setting</button></form></div></div><div class="card roster-card mt-3"><div class="card-body"><h5>Existing Workflows</h5>@foreach($workflows as $w)<div class="border rounded p-2 mb-2"><strong>{{ $w->name }}</strong>@if($w->is_default)<span class="badge bg-primary">Default</span>@endif<div class="small text-muted">{{ $w->levels->pluck('label')->join(' → ') }}</div></div>@endforeach</div></div></div><div class="col-lg-8"><div class="card roster-card"><div class="card-body"><h5>Create Approval Workflow</h5><div class="help-inline mb-3">Default design: Unit In-Charge → Consultant → Director / Deputy Director. Super Admin can create different role/category/user chains and unit-specific workflows.</div><form method="post" action="{{ route('roster.settings.workflow.store') }}">@csrf<div class="row g-2"><div class="col-md-5"><label>Name</label><input required class="form-control" name="name" value="Default Hospital Roster Approval"></div><div class="col-md-5"><label>Applies to Unit</label><select class="form-select" name="unit_id"><option value="">All Units</option>@foreach($units as $u)<option value="{{ $u->id }}">{{ $u->name }}</option>@endforeach</select></div><div class="col-md-2 d-flex align-items-end"><label class="form-check"><input class="form-check-input" type="checkbox" name="is_default" value="1"> Default</label></div></div><hr><div id="levels"></div><button type="button" class="btn btn-sm btn-outline-primary" onclick="addLevel()">+ Add Level</button><div><button class="btn btn-steel mt-3">Save Workflow</button></div></form></div></div></div></div></div><script>let lv=[{label:'Unit In-Charge',type:'initiator',categories:''},{label:'Consultant',type:'category',categories:'Consultant'},{label:'Director / Deputy Director',type:'category',categories:'Director, Deputy Director'}];function render(){levels.innerHTML=lv.map((x,i)=>`<div class="slot-row"><div class="row g-2"><div class="col-md-3"><label>Level ${i+1} Label</label><input required class="form-control" name="levels[${i}][label]" value="${x.label}"></div><div class="col-md-2"><label>Approver Type</label><select class="form-select" name="levels[${i}][approver_type]"><option value="initiator" ${x.type==='initiator'?'selected':''}>Initiator</option><option value="category" ${x.type==='category'?'selected':''}>Category</option><option value="role" ${x.type==='role'?'selected':''}>Role</option><option value="user" ${x.type==='user'?'selected':''}>Specific User IDs</option></select></div><div class="col-md-3"><label>Categories (comma-separated)</label><input class="form-control" name="levels[${i}][categories]" value="${x.categories||''}"></div><div class="col-md-2"><label>Roles</label><input class="form-control" name="levels[${i}][roles]" value="${x.roles||''}"></div><div class="col-md-1"><label>User IDs</label><input class="form-control" name="levels[${i}][user_ids]"></div><div class="col-md-1 d-flex align-items-end"><button type="button" class="btn btn-outline-danger" onclick="lv.splice(${i},1);render()">×</button></div><div class="col-md-3 form-check mt-2 ms-2"><input type="checkbox" class="form-check-input" name="levels[${i}][is_required]" value="1" checked><label>Required</label></div><div class="col-md-3 form-check mt-2"><input type="checkbox" class="form-check-input" name="levels[${i}][allow_return]" value="1" ${i?'checked':''}><label>Allow return</label></div></div></div>`).join('')}function addLevel(){lv.push({label:'Approval Level',type:'category'});render()}render();</script>@endsection